//------------------------------------------------------------------------------------------------
//Queries sys_dictionary for all related records
//----------------------------------------------------------------------
//Pass refTbl as Table Name (i.e. sys_user, incident, cmn_location, etc.)
//Pass userRecord as user sys_id (i.e. 28dd2c721bef8ad0c73ceca5604bcb32)
//------------------------------------------------------------------------------------------------
function findDictionaryReferences(refTbl, userRecord) {

    var snTables = this.findTables();

    var msg = [];
    //Query dictionary table for Task and CMDB Tables
    var dict = new GlideRecord('sys_dictionary');
    dict.addQuery('name', 'IN', snTables);
    //dev SysID for User table
    dict.addQuery('reference', refTbl);
    dict.query();

        while (dict.next()) {
            try {
                var tblName = dict.name.toString();
                var refType = dict.internal_type;

                //Query each table for matching records
                var rec = new GlideRecord(tblName);
                if (refType == 'glide_list' || refType == 'conditions') {
                    rec.addQuery(dict.element, 'CONTAINS', userRecord);
                } else {
                    rec.addQuery(dict.element, userRecord);
                }
                rec.query();
                //Add sys_id to array
                while (rec.next()) {
                    msg.push(tblName + ': ' + rec.sys_id);
                }
            }
            catch (error) {
                gs.info(error + "Error in table" + tblName);
            }
        }

    return msg;
}


//------------------------------------------------------------------------------------------------
//Queries Submitted Variables to update accordingly
//Pass userRecord as sys_id (string)
//------------------------------------------------------------------------------------------------
function findVariableReferences(userRecord) {
    var msg = [];
    tblName = 'sys_variable_value';

    var vVal = new GlideRecord(tblName);
    vVal.addQuery('value', 'CONTAINS', userRecord);
    vVal.query();
    //Add sys_id to array
    while (vVal.next()) {
        msg.push(tblName + ': ' + vVal.sys_id);
    }

    return msg;
}

//------------------------------------------------------------------------------------------------
//Queries sys_db_object to find all tables that extend Task [task] and CMDB [cmdb]
//------------------------------------------------------------------------------------------------
function findTables() {
    var taskTable = 'task';
    var tableUtil = new TableUtils(taskTable);
    var taskTables = tableUtil.getTableExtensions().toArray();

    var cmdbTable = 'cmdb';
    var tableUtil = new TableUtils(cmdbTable);
    var cmdbTables = tableUtil.getTableExtensions().toArray();

    var allTables = taskTables.concat(cmdbTables);
    return allTables;
}

/////////////////////////////////////////////////////////////////////////////////////////

function findDictionaryReferences(refTbl, gu, bu) {
    var dict = new GlideRecord('sys_dictionary');
    dict.addQuery('name', 'IN', snTables);
    //dev SysID for User table
    dict.addQuery('reference', refTbl);
    dict.query();

    while(dict.next()) {
        try {
            var tblName = dict.name.toString();

            var refType = dict.internal_type;

            var rec = new GlideRecord(tblName);
            if (refType == 'glide_list' || refType == 'conditions') {
                rec.addQuery(dict.element, 'CONTAINS', bu);
            } else {
                rec.addQuery(dict.element, bu);
            }
            rec.query();
            //Add sys_id to array
            while(rec.next()){
                    var tblPair = [];
                    //msg.push(tblName+': '+rec.sys_id);
                    tblPair.push('"tblName": "' + tblName + '"');
                    tblPair.push('"sys_id": "' + rec.sys_id + '"');
                    msg.push(tblPair);
            }
        }
        catch (error) {
            gs.info(error + "Error in table" + tblName);
        }
    }
}

function findVariableReferences(gu, bu) {
    //Query for workflow variable values
    tblName = 'sys_variable_value';
    var vVal = new GlideRecord(tblName);
    vVal.addQuery('value', 'CONTAINS', bu);
    vVal.query();
    //Add sys_id to array
    while (vVal.next()){
        msg.push(tblName+': '+vVal.sys_id);
        vVal.setValue('value', gu);
    }
}

var arrayUtils = new ArrayUtil();
var msgUtils = arrayUtils.unique(msg);

gs.info(msgUtils);
gs.info(msgUtils.length);
